    $db->exec("INSERT INTO clubs VALUES('own-cover-recovery','Own donation cover recovery');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-cover-recovery-admin','own-cover-recovery','members',1),('own-cover-recovery-finance','own-cover-recovery','treasurer',0),('own-cover-recovery-other','own-cover-recovery','treasurer',0)");
    $settings=new \Kulturhus\Verein\Settings($db,$admin);$writeRole=$settings->saveRole('',0,['name'=>'Own recovery cover finance only','members_access'=>'none','finance_access'=>'write','settings_access'=>false]);foreach([$actor,$other]as$id)$settings->assignRole($id,$writeRole,0);
