    $docs=new \Kulturhus\Verein\Documents($db,$admin);$notice=$docs->upload('own-cover-tax-notice.pdf',recoveryTransferPdf('owned cover tax notice'),['title'=>'Own cover tax notice','kind'=>'other','scope'=>'finance','document_date'=>'2025-02-01','links'=>[]],$key());
    $settings->save('tax',array_replace(\Kulturhus\Verein\SettingsSchema::defaults('tax'),['office'=>'Own recovery tax office','number'=>'00/000/00000','purpose'=>'Förderung von Kunst und Kultur','notice_type'=>'exemption','exemption_date'=>'2025-02-01','assessment'=>'2022 bis 2024','membership_deductible'=>'no','notice_document_id'=>$notice,'receipt_signatory'=>'Own recovery tax authority','receipt_authority_reviewed'=>true]),0);
    $templates=\Kulturhus\Verein\SettingsSchema::templates('texts_donations');foreach(['donation','collective']as$type)$templates[$type]=['subject'=>'Own recovered '.$type.' {{ZAHLBETRAG}}','intro'=>'Own original introduction 0','message'=>"{{BRIEFANREDE}}\nOwn original complete body {{ZAHLBETRAG}}",'closing'=>'Own original closing 0'];$settings->save('texts_donations',$templates,0);
    $finance=new \Kulturhus\Verein\Finance($db,$admin);$account=$finance->createAccount('Own cover recovery offline source','offline','0','2026-01-01');$registry=new \Kulturhus\Verein\Registry($db,$admin);$requests=new \Kulturhus\Verein\Finance\Donations\Cover\CoverRequests($db,$actor);$sources=[];$firsts=[];$files=[];$coverPdfs=[];
    foreach(['donation','collective']as$type){
        $contact=$registry->saveContact(null,0,'person','Own original recovered '.$type.' donor',$type.'@example.invalid',"Own exact original street 7\n12345 Own town");$entries=[];$payments=[];
        foreach($type==='collective'?['25.01','40.02']:['125.50']as$i=>$amount){$entry=$finance->createEntry(['kind'=>'donation','description'=>'Own genuine recovered '.$type.' donation','counterparty'=>'Own original recovered '.$type." donor\nOwn exact original street 7\n12345 Own town",'category'=>'donations','amount'=>$amount,'document_date'=>'2026-08-01','due_date'=>'2026-08-01'],$key());$finance->assignDonationContact('entry',$entry,1,$contact);$finance->recordPayment($entry,2,$account,'2026-08-0'.($i+1));$entries[]=$entry;$payments[]=$finance->allocations($entry)[0]['id'];}
        if($type==='collective'){$service=new \Kulturhus\Verein\DonationCollections($db,$admin);$raw=['contact_id'=>$contact,'from'=>'2026-01-01','to'=>'2026-08-31','payment_ids'=>$payments,'waiver_ids'=>[],'reviewed'=>'1'];$preview=$service->build($raw);$document=$service->issue($raw,$key(),hash('sha256',json_encode($preview,JSON_THROW_ON_ERROR)));}
        else{$raw=(new \Kulturhus\Verein\DonationForms($db,$admin))->defaults('money',$entries[0])+['receipt_reviewed'=>'1'];$raw['waiver']='no';$document=(new \Kulturhus\Verein\DonationReceipts($db,$admin))->issue($raw,$key());}
        $file=$docs->file($document,1);$snapshot=json_decode($file['snapshot'],true,64,JSON_THROW_ON_ERROR);$receipt=$snapshot['receipt_number'];$input=$requests->initial($receipt,'2026-10-22');$input['reason']="\n0\r\nOwn exact original recovery reason 🙂";$input['text']['message']="\n0 <b>Own original literal text</b> 🙂\r\n".$input['text']['message'];$review=$requests->prepare($input);$first=$requests->accept($input,$key(),$review['hash'],true);$firsts[$type]=$first;$sources[$type]=compact('document','receipt','contact','entries');$file['bytes']=base64_encode($file['bytes']);$files[$type]=$file;$coverPdfs[$type]=base64_encode($requests->pdf($first['key']));
        $registry->saveContact($contact,1,'person','Own genuinely later '.$type.' donor','later-'.$type.'@example.invalid','Own later changed address');
    }
    $templates['donation']['subject']='Own later single cover {{ZAHLBETRAG}}';$templates['collective']['subject']='Own later collective cover {{ZAHLBETRAG}}';$settings->save('texts_donations',$templates,1);
    return compact('club','admin','actor','other','sources','firsts','files','coverPdfs');
}
function recoveryDonationCoverSeal(PDO $db,array $original):array
{
    $rows=[];foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as$table){$columns=$db->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll(PDO::FETCH_COLUMN);if(in_array('club_id',$columns,true))$rows[$table]=\Kulturhus\Native\Shared\Db::run($db,'SELECT * FROM `'.$table.'` WHERE club_id=?',[$original['club']])->fetchAll();}
    foreach($rows as&$tableRows)usort($tableRows,static fn(array $a,array $b):int=>strcmp(serialize($a),serialize($b)));unset($tableRows);
    // Binary certificate and cover bytes are separately verified above and below.
    foreach($rows['document_files']as&$row)$row['bytes']=base64_encode($row['bytes']);unset($row);$original['rows']=$rows;return $original;
}
